// Builds editor/neodoc-editor.html: one self-contained page that runs from a
// `file://` URL — no server, no network, no build artifacts to install.
//
//   node tools/bundle.js           write editor/neodoc-editor.html
//   node tools/bundle.js --check   exit 1 if the committed file is stale
//
// Only the module syntax this repo actually uses is supported: relative
// side-effect-free `import { … } from './x.js'` and top-level
// `export function|const|let|var|class` / `export { … }`. Anything else fails
// loudly rather than producing a subtly broken page.

import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const ENTRY = resolve(ROOT, 'editor/editor.js');
const PAGE = resolve(ROOT, 'editor/index.html');
const OUT = resolve(ROOT, 'editor/neodoc-editor.html');

const IMPORT = /^import\s+\{([^}]*)\}\s+from\s+'([^']+)';\s*$/gm;
const EXPORT_DECL = /^export\s+(?:async\s+)?(?:function\s*\*?|const|let|var|class)\s+([A-Za-z0-9_$]+)/gm;
const EXPORT_LIST = /^export\s*\{([^}]*)\}\s*;?\s*$/gm;

// Module ids must be identical on every OS: `path.relative` yields backslashes on
// Windows, which would make the generated page differ byte-for-byte by platform.
const idOf = (path) => relative(ROOT, path).replace(/\\/g, '/').replace(/\.js$/, '');

function readModule(path, ordered, seen, stack = new Set()) {
  if (seen.has(path)) return;
  if (stack.has(path)) throw new Error(`circular import at ${idOf(path)}`);
  stack.add(path);
  const source = readFileSync(path, 'utf8');
  for (const [, , spec] of source.matchAll(IMPORT)) {
    if (!spec.startsWith('.')) throw new Error(`${idOf(path)}: only relative imports are supported (${spec})`);
    readModule(resolve(dirname(path), spec), ordered, seen, stack);
  }
  stack.delete(path);
  seen.add(path);
  ordered.push([path, source]);
}

function transform(path, source) {
  const id = idOf(path);
  const exported = [];
  let body = source.replace(IMPORT, (_m, names, spec) => {
    if (/\sas\s/.test(names)) {
      throw new Error(`${id}: \`import { x as y }\` is not supported by this bundler — rename at the definition, or teach tools/bundle.js the alias`);
    }
    const dep = idOf(resolve(dirname(path), spec));
    return `const {${names.replace(/\s+/g, ' ').trim()}} = __mods[${JSON.stringify(dep)}];`;
  });
  body = body.replace(EXPORT_DECL, (_m, name) => {
    exported.push(name);
    return _m.replace(/^export\s+/, '');
  });
  body = body.replace(EXPORT_LIST, (_m, list) => {
    for (const raw of list.split(',')) {
      const name = raw.trim();
      if (!name) continue;
      // `export { a as b }` used to be recorded as `a`: the bundle would compile and
      // then hand dependents the wrong name. Fail loudly instead.
      if (/\sas\s/.test(name)) {
        throw new Error(`${id}: \`export { x as y }\` is not supported by this bundler — export it under its own name, or teach tools/bundle.js the alias`);
      }
      exported.push(name);
    }
    return '';
  });
  if (/^\s*(?:import|export)\s/m.test(body)) throw new Error(`${id}: unsupported module syntax (see the header of tools/bundle.js)`);
  if (/import\s*\(/.test(body)) throw new Error(`${id}: dynamic import() cannot be bundled`);
  // Awaiting each module in dependency order preserves import semantics even for
  // modules that use top-level `await`, and keeps every module's privates scoped.
  return `await (async function () {\n${body}\n__mods[${JSON.stringify(id)}] = {${exported.join(', ')}};\n})();\n`;
}

/** @returns {string} the self-contained editor page. */
export function bundle() {
  const ordered = [];
  readModule(ENTRY, ordered, new Set());
  const code = [
    '// Generated by tools/bundle.js from editor/editor.js + src/*.js — do not edit by hand.',
    'const __mods = {};',
    ...ordered.map(([path, source]) => transform(path, source)),
  ].join('\n');

  const css = readFileSync(resolve(ROOT, 'editor/editor.css'), 'utf8');
  const page = readFileSync(PAGE, 'utf8');
  // Function replacements, not strings: the bundled code contains `$&` and other
  // `$` patterns (src/markdown.js escapes with them) which String.replace would
  // expand into the matched text, injecting a literal <script src="editor.js"> tag
  // into the code — which then closes the inline script and breaks the page.
  const withCss = page.replace(/<link[^>]*href="editor\.css"[^>]*>/, () => `<style>\n${css}</style>`);
  // Still a module script: it lets the editor keep its top-level `await`, and an
  // inline module needs no fetch, so this page works from a `file://` URL.
  const withJs = withCss.replace(/<script type="module" src="editor\.js"><\/script>/, () => `<script type="module">\n${code}</script>`);
  if (withJs === withCss || withJs === page) throw new Error('editor/index.html no longer has the <link href="editor.css"> + <script src="editor.js"> pair this bundler rewrites');
  return withJs;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const html = bundle();
  if (process.argv.includes('--check')) {
    let current = '';
    try { current = readFileSync(OUT, 'utf8'); } catch { /* missing counts as stale */ }
    if (current !== html) {
      process.stderr.write('editor/neodoc-editor.html is stale — run: node tools/bundle.js\n');
      process.exit(1);
    }
    process.stdout.write('editor/neodoc-editor.html is up to date\n');
  } else {
    writeFileSync(OUT, html);
    process.stdout.write(`editor/neodoc-editor.html  ${html.length} bytes\n`);
  }
}
